def dijkstra(graph, start):
    n = len(graph)
    if n == 0 or start < 0 or start >= n:
        return []
    inf = float('inf')
    dist = list(graph[start])
    done = [False] * n
    for _ in range(n):
        u = -1
        for v in range(n):
            if not done[v] and (u == -1 or dist[v] < dist[u]):
                u = v
        if dist[u] == inf:
            break
        done[u] = True
        for v in range(n):
            if not done[v] and graph[u][v] != inf and dist[u] + graph[u][v] < dist[v]:
                dist[v] = dist[u] + graph[u][v]
    return dist

def make(n, edges):
    inf = float('inf')
    matrix = [[inf] * n for _ in range(n)]
    for i in range(n):
        matrix[i][i] = 0
    for u, v, w in edges:
        matrix[u][v] = w
    return matrix

example = make(6, [(0, 1, 10), (0, 4, 5), (1, 2, 1), (1, 4, 2), (2, 3, 4),
                   (3, 0, 7), (3, 2, 6), (4, 1, 3), (4, 2, 9), (4, 3, 2)])
print(dijkstra(example, 0))
print(dijkstra([], 0))
print(dijkstra([[0]], 9))
print(dijkstra([[0]], 0))

